// The skeleton's content (data/skeleton.json, generated by @aue/data): its map is in route coordinates, and the
// simulation runs it to the end the same way twice.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createWorld, step, stateHash, attrs } from '@aue/sim';
import { skeletonContent as c, skeletonSource, timingSource } from '../src/index.js';

test('[地图-1] tiles are in route coordinates: start tiles at the top, every route starts on one', () => {
  const { tiles, height, routes } = c.level;
  const startRows = tiles.flatMap((row, r) => row.map((t) => (t.key.startsWith('tile_start') ? r : -1))).filter((r) => r >= 0);
  assert.ok(startRows.length > 0 && startRows.every((r) => r >= height - 2), `start tiles on rows ${startRows}`);
  for (const route of routes) assert.match(tiles[route.start.row][route.start.col].key, /^tile_start/, JSON.stringify(route.start));
  assert.match(skeletonSource.commit, /^[0-9a-f]{40}$|^unknown$/);
});

test('the skeleton plays out the same way twice', () => {
  /** @returns {number[]} */
  const play = () => {
    const w = createWorld(c, { seed: 42, players: 2 }), out = [];
    for (let f = 0; f < 4000; f++) {
      /** @type {[number, import('@aue/sim').Command][]} */
      const cmds = f === 0 ? [[0, { type: 'deploy', op: 'char_503_rang', row: 3, col: 2, dir: 0 }], [1, { type: 'deploy', op: 'char_502_nblade', row: 4, col: 5, dir: 2 }]] : [];
      step(w, c, cmds);
      if (f === 0) assert.equal(w.units.filter((u) => u.kind === 0).length, 2, 'both deploys succeed');
      if (f % 100 === 0) out.push(stateHash(w));
    }
    return out;
  };
  assert.deepEqual(play(), play());
});

test('[技能-3] [技能-5] the skeleton’s 米格鲁 starts 防御力强化·α型 by command once she holds 45 SP: def × 1.3 for 30 s', () => {
  const quiet = { ...c, level: { ...c.level, spawns: [] } }, w = createWorld(quiet, { seed: 1, players: 1 });
  const tile = c.level.tiles.flatMap((row, r) => row.map((t, col) => ({ t, r, col }))).find((x) => x.t.buildable === 'MELEE' || x.t.buildable === 'ALL');
  assert.ok(tile);
  assert.equal(c.operators.char_122_beagle.cost, 16);
  w.players[0].cost = 16;
  step(w, quiet, [[0, { type: 'deploy', op: 'char_122_beagle', row: tile.r, col: tile.col, dir: 0 }]]);
  const b = w.units[0], def = attrs.statsOf(b).def;
  assert.equal(b.skill?.cost, 45);
  for (let f = 0; f < 45 * 30; f++) step(w, quiet);
  assert.equal(b.skill?.sp, 45);
  const ev = step(w, quiet, [[0, { type: 'skill', unit: b.id }]]);
  assert.deepEqual(ev.filter((e) => e.type === 'skill'), [{ type: 'skill', id: b.id, active: 1 }]);
  assert.equal(attrs.statsOf(b).def, def * 1.3);
});

test('[攻击-2] the skeleton units carry their attack clip timing from data/timings.json; one without an attack clip has none', () => {
  assert.deepEqual(c.operators.char_502_nblade.attack, { duration: 1, hit: Math.fround(0.26666668) });
  assert.deepEqual(c.enemies.enemy_1404_msnip.attack, { duration: Math.fround(1.3666667), hit: Math.fround(0.6333333) });
  assert.equal(c.enemies.enemy_3001_upeopl.attack, undefined);
  assert.match(timingSource.operators, /^HX0922\/ArknightsSpine@[0-9a-f]{40}/);
  assert.match(timingSource.enemies, /^isHarryh\/Ark-Models@[0-9a-f]{40}$/);
});
